From 56df22a0476d7dc1dfa3a1244ce4ff51b22a4f43 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 05:40:55 +0100
Subject: [PATCH] plasmacomponents: make text fields follow system font changes

The Plasma Kirigami theme read the font only once and text fields kept
the font Qt gave them on creation, so search fields ignored font changes
until restart. Now the theme follows them and TextField binds to it.

BUG: 519438
---
 .../kirigamiplasmastyle/plasmatheme.cpp       | 67 ++++++++++++++-----
 .../kirigamiplasmastyle/plasmatheme.h         |  1 +
 .../plasmacomponents3/TextField.qml           |  1 +
 3 files changed, 53 insertions(+), 16 deletions(-)

diff --git a/src/declarativeimports/kirigamiplasmastyle/plasmatheme.cpp b/src/declarativeimports/kirigamiplasmastyle/plasmatheme.cpp
index eb317484e..c61135395 100644
--- a/src/declarativeimports/kirigamiplasmastyle/plasmatheme.cpp
+++ b/src/declarativeimports/kirigamiplasmastyle/plasmatheme.cpp
@@ -19,6 +19,32 @@
 #include <KConfigGroup>
 #include <KIconColors>

+namespace
+{
+class FontWatcher : public QObject
+{
+public:
+    FontWatcher()
+    {
+        qGuiApp->installEventFilter(this);
+    }
+
+    QList<PlasmaTheme *> themes;
+
+protected:
+    bool eventFilter(QObject *watched, QEvent *event) override
+    {
+        if (watched == qGuiApp && event->type() == QEvent::ApplicationFontChange) {
+            for (PlasmaTheme *theme : std::as_const(themes)) {
+                theme->syncFonts();
+            }
+        }
+        return false;
+    }
+};
+Q_GLOBAL_STATIC(FontWatcher, s_fontWatcher)
+}
+
 PlasmaTheme::PlasmaTheme(QObject *parent)
     : PlatformTheme(parent)
 {
@@ -36,22 +62,8 @@ PlasmaTheme::PlasmaTheme(QObject *parent)
         });
     }

-    setDefaultFont(qGuiApp->font());
-
-    KSharedConfigPtr ptr = KSharedConfig::openConfig();
-    KConfigGroup general(ptr->group(QStringLiteral("general")));
-
-    setSmallFont(general.readEntry("smallestReadableFont", []() {
-        auto smallFont = qApp->font();
-#ifndef Q_OS_WIN
-        if (smallFont.pixelSize() != -1) {
-            smallFont.setPixelSize(smallFont.pixelSize() - 2);
-        } else {
-            smallFont.setPointSize(smallFont.pointSize() - 2);
-        }
-#endif
-        return smallFont;
-    }()));
+    syncFonts();
+    s_fontWatcher->themes.append(this);

     syncWindow();
     syncColors();
@@ -60,6 +72,9 @@ PlasmaTheme::PlasmaTheme(QObject *parent)

 PlasmaTheme::~PlasmaTheme()
 {
+    if (!s_fontWatcher.isDestroyed()) {
+        s_fontWatcher->themes.removeOne(this);
+    }
 }

 QIcon PlasmaTheme::iconFromTheme(const QString &name, const QColor &customColor)
@@ -164,6 +179,26 @@ void PlasmaTheme::syncColors()
     setFrameContrast(KColorScheme::frameContrast());
 }

+void PlasmaTheme::syncFonts()
+{
+    setDefaultFont(qGuiApp->font());
+
+    KSharedConfigPtr ptr = KSharedConfig::openConfig();
+    KConfigGroup general(ptr->group(QStringLiteral("general")));
+
+    setSmallFont(general.readEntry("smallestReadableFont", []() {
+        auto smallFont = qApp->font();
+#ifndef Q_OS_WIN
+        if (smallFont.pixelSize() != -1) {
+            smallFont.setPixelSize(smallFont.pixelSize() - 2);
+        } else {
+            smallFont.setPointSize(smallFont.pointSize() - 2);
+        }
+#endif
+        return smallFont;
+    }()));
+}
+
 void PlasmaTheme::syncFrameContrast()
 {
     if (QCoreApplication::closingDown()) {
diff --git a/src/declarativeimports/kirigamiplasmastyle/plasmatheme.h b/src/declarativeimports/kirigamiplasmastyle/plasmatheme.h
index 462c8713d..3aedf13d8 100644
--- a/src/declarativeimports/kirigamiplasmastyle/plasmatheme.h
+++ b/src/declarativeimports/kirigamiplasmastyle/plasmatheme.h
@@ -31,6 +31,7 @@ public:
     void syncWindow();
     void syncColors();
     void syncFrameContrast();
+    void syncFonts();

 protected:
     bool event(QEvent *event) override;
diff --git a/src/declarativeimports/plasmacomponents3/TextField.qml b/src/declarativeimports/plasmacomponents3/TextField.qml
index ea65dc088..902cbd701 100644
--- a/src/declarativeimports/plasmacomponents3/TextField.qml
+++ b/src/declarativeimports/plasmacomponents3/TextField.qml
@@ -66,6 +66,7 @@ T.TextField {
     Kirigami.Theme.inherit: !background || !background.visible
     Kirigami.Theme.colorSet: Kirigami.Theme.View

+    font: Kirigami.Theme.defaultFont
     color: Kirigami.Theme.textColor
     selectionColor: Kirigami.Theme.highlightColor
     selectedTextColor: Kirigami.Theme.highlightedTextColor
